"""Render docs/JURIS_ROBUSTNESS.md from data/juris/reports/robustness.json (so the write-up cannot drift from the results)."""

import json
import sys

from scripts.juris import paths

DOC = paths.BACKEND.parent / "docs" / "JURIS_ROBUSTNESS.md"


def pc(x: float, d: int = 1) -> str:
    return f"{100 * x:.{d}f} %"


def main() -> None:
    R = json.loads((paths.REPORT_DIR / "robustness.json").read_text())
    L = ["# Juris: robustness and sensitivity analyses", "",
         "Generated by `scripts/juris/render_robustness_md.py` from `data/juris/reports/robustness.json` (produced by `scripts/juris/robustness.py`, "
         "`neural_probe.py` and `ildc_check.py`). Everything uses the development years (up to 2022) **except** the two items marked *test split*, which are disclosed below.", ""]
    f = R["frozen_model_test_analysis"]
    L += ["## Reproducibility", "", f"Re-fitting the frozen shipped configuration reproduces the reported test result exactly: **{pc(f['acc'])} accuracy, AUC {f['auc']:.3f}** "
          f"(match with `final.json`: {f['reproduces_final_report']}). *Test split, same frozen model, descriptive analysis only; nothing was chosen from it.*", ""]
    L += ["## Selective prediction (test split, same frozen model)", "", "If Juris answers only the cases it is most sure about:", "",
          "| Share of cases answered | Accuracy | Cases |", "|---|---|---|"] + [f"| {pc(c['coverage'], 0)} | {pc(c['accuracy'])} | {c['n']:,} |" for c in f["selective_prediction"]] + [
          "", f"Always guessing the majority outcome scores {pc(f['majority_acc_all'])} on all cases.", ""]
    g = f["subgroups_test"]
    L += ["## Bail-type appeals versus the rest (test split, same frozen model)", "", "| Group | Cases | Share that succeeded | Accuracy | Balanced acc. | AUC |", "|---|---|---|---|---|---|"] + [
          f"| {k} | {v['n']:,} | {pc(v['succeeds_share'], 0)} | {pc(v['acc'])} | {pc(v['bal_acc'])} | {v['auc']:.3f} |" for k, v in g.items()] + [""]
    L += ["## Sensitivity to the pre-reasoning cut (validation year, 20,000 training cases)", "",
          "| Cap on the text kept | Reasoning cues | Mean words kept | Accuracy | AUC |", "|---|---|---|---|---|"] + [
          f"| {pc(r['cap'], 0)} | {'on' if r['reasoning_cues'] else 'off'} | {r['mean_words_kept']:.0f} | {pc(r['acc'])} | {r['auc']:.3f} |" for r in R["cut_sensitivity_val2022"]] + [
          "", "The cap barely matters (AUC moves 0.015 between 30 % and 90 %); the reasoning-cue cut matters a great deal, which is what the leakage ladder predicts.", ""]
    L += ["## Rolling-origin evaluation (train on all earlier years, test the next one)", "", "| Train years | Test year | Juris acc. | Juris AUC | Majority acc. | Appeal-type-only AUC |", "|---|---|---|---|---|---|"] + [
          f"| {r['train_years']} | {r['test_year']} | {pc(r['acc'])} | {r['auc']:.3f} | {pc(r['majority_acc'])} | {r['side_only_auc']:.3f} |" for r in R["rolling_origin"]] + [""]
    if "leave_one_bench_out_to2022" in R:
        L += ["## Leave-one-bench-out (decisions up to 2022; the held-out bench is never seen in training)", "", "| Held-out bench | Cases | Juris acc. | Juris AUC | Majority acc. |", "|---|---|---|---|---|"] + [
              f"| {r['held_out_bench']} | {r['n_eval']:,} | {pc(r['acc'])} | {r['auc']:.3f} | {pc(r['majority_acc'])} |" for r in R["leave_one_bench_out_to2022"]] + [""]
    L += ["## Ablations (validation year, 20,000 training cases)", "", "| Variant | Accuracy | AUC |", "|---|---|---|"] + [
          f"| {k} | {pc(v['acc'])} | {v['auc']:.3f} |" for k, v in R["ablations_val2022_trained_on_20k"].items()] + [
          "", "The wording carries almost all the signal: removing the explicit appeal-type input costs 0.003 AUC (the text already reveals who is appealing), and the cited-section indicators add nothing.", ""]
    s = R["side_specific_models_val2022"]
    t = R.get("state_specific_model_test_second_look")
    L += ["## Separate models per appeal side", "", "| Side | Validation cases | Joint-model AUC within the side | Side-specific model AUC |", "|---|---|---|---|"] + [
          f"| {k} | {v['n_val']:,} | {v['joint_model_auc_within_side']:.3f} | {v['side_specific_model_auc']:.3f} |" for k, v in s.items()] + [""]
    if t:
        a, b = t["joint model, State appeals"], t["State-specific model, State appeals"]
        c, d = t["joint model, all test cases"], t["combined (State-specific for State appeals), all test cases"]
        L += ["**Disclosed second use of the test split.** The State-appeal model was chosen on validation data (above), then evaluated once on the test period:", "",
              "| Test cases | Joint model AUC | With the State-specific model | Joint Brier | With the State-specific model |", "|---|---|---|---|---|",
              f"| State appeals ({t['n_state_test']:,}; {pc(t['state_test_succeeds_share'], 0)} succeed) | {a['auc']:.3f} | **{b['auc']:.3f}** | {a['brier']:.3f} | {b['brier']:.3f} |",
              f"| All cases | {c['auc']:.3f} | {d['auc']:.3f} | {c['brier']:.3f} | {d['brier']:.3f} |", "",
              "Accuracy is unchanged (State appeals are almost always dismissed, so the model still says so); what improves is the ranking within State appeals, which the shipped joint model could not do. It is a validated candidate, **not yet shipped**.", ""]
    n = R["neural_probe_val2022"]
    key = [k for k in n if k.startswith("embeddings_plus")][0]
    L += ["## Neural baseline (frozen InLegalBERT, local, validation year)", "",
          f"{n['n_train']:,} training and {n['n_val']:,} validation cases, the same for every row; embeddings are the mean over the first 512 tokens of the pre-reasoning text.", "",
          "| Model | AUC | Balanced acc. |", "|---|---|---|", f"| Frozen InLegalBERT + appeal type (logistic head) | {n[key]['auc']:.3f} | {pc(n[key]['bal_acc'])} |",
          f"| TF-IDF model (Juris recipe) | {n['tfidf_model_same_cases']['auc']:.3f} | {pc(n['tfidf_model_same_cases']['bal_acc'])} |",
          f"| Late fusion (rank average) | {n['late_fusion (rank average)']['auc']:.3f} | {pc(n['late_fusion (rank average)']['bal_acc'])} |", "",
          "A frozen encoder that sees only the first 512 tokens does not beat TF-IDF here, and fusing them adds nothing. Fine-tuning was not tried (it needs a GPU).", ""]
    L += ["## The same recipe on ILDC (Supreme Court, 35k cases, outcome text removed by its authors)", "", "| Split | Train / test | Accuracy (95 % CI) | AUC | Majority acc. |", "|---|---|---|---|---|"]
    for k in ("ildc_temporal_check", "ildc_random_split_check"):
        if k in R:
            r = R[k]
            L.append(f"| {r['dataset'].split(', ')[-1]} | {r['n_train']:,} / {r['n_test']:,} | {pc(r['acc'])} ({pc(r['acc_ci95'][0])}-{pc(r['acc_ci95'][1])}) | {r['auc']:.3f} | {pc(r['majority_acc'])} |")
    L += ["", "The public copy has no official split, so these are **not** the published splits; the authors' best model (a hierarchical transformer) reports 78 % on their own. "
          "They show that the plain TF-IDF recipe is a sensible baseline on ILDC (70 % on a random split) and that a temporal split costs about 7 points.", "",
          "## What this does and does not show", "",
          "- Juris's advantage over the trivial baselines holds in every test year and on benches it has never seen, and it can abstain usefully.",
          "- It does not show state-of-the-art accuracy, a neural gain, or generalisation to other courts (the Supreme Court cross-check was not run).",
          "- No human audit of the leakage cut or the labels has been done: `data/juris/release/audit_sample_200.csv` is the sheet for it."]
    DOC.write_text("\n".join(L) + "\n")
    print(f"wrote {DOC}")


if __name__ == "__main__":
    sys.exit(main())
